param([Parameter(Mandatory=$true)][string]$OutputDirectory,[Parameter(Mandatory=$true)][string]$ResearchDirectory)
$ErrorActionPreference='Stop';if($PSVersionTable.PSVersion.Major -lt 7){throw 'Use pwsh.exe'}
$mwCDRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$mwCDOut=[IO.Path]::GetFullPath($OutputDirectory);$mwCDResearch=(Resolve-Path -LiteralPath $ResearchDirectory).Path;$mwCDAllowed=Join-Path $mwCDRoot 'reports/m4-crt-control-carry'
if(-not $mwCDOut.StartsWith($mwCDAllowed+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase) -or -not $mwCDResearch.StartsWith($mwCDAllowed+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'Private control evidence required'}
$mwCDName=Split-Path $mwCDOut -Leaf;if($mwCDName -notmatch '^[a-z][a-z0-9-]{0,63}$' -or $mwCDName -match '^(con|prn|aux|nul|com[0-9]|lpt[0-9])$'){throw 'Fresh simple control experiment name'}
$mwCDBuild=Join-Path $mwCDRoot "build/m4-crt-control-carry-$mwCDName";if((Test-Path -LiteralPath $mwCDOut) -or (Test-Path -LiteralPath $mwCDBuild)){throw 'Fresh original control report/build required'}
function Get-MWCDHash([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
$mwCDProvider=Join-Path $mwCDRoot 'local/mw3-staged/Shared_DLLs/MSVCRT.DLL';if((Get-MWCDHash $mwCDProvider) -ne '2d5670881a6d13a100e37da297f6eeb876f68b63073a28eb5d650625c60f9bf7'){throw 'Exact provider identity required'}
$mwCDSources=[ordered]@{};foreach($mwCDFile in @(Get-ChildItem -LiteralPath (Join-Path $mwCDResearch 'original') -File -Recurse;Get-Item -LiteralPath $PSCommandPath,(Join-Path $PSScriptRoot 'original/CMakeLists.txt'),(Join-Path $PSScriptRoot 'generate.py'),(Join-Path $mwCDResearch 'generation.json'))|Sort-Object FullName){$mwCDSources[$mwCDFile.FullName]=Get-MWCDHash $mwCDFile.FullName}
New-Item -ItemType Directory $mwCDOut|Out-Null;$mwCDCopies=[Collections.Generic.List[object]]::new();foreach($mwCDPath in $mwCDSources.Keys){$mwCDCopy=Join-Path (Join-Path $mwCDOut 'sources') ([IO.Path]::GetRelativePath($mwCDRoot,$mwCDPath));New-Item -ItemType Directory -Force -Path (Split-Path $mwCDCopy)|Out-Null;Copy-Item -LiteralPath $mwCDPath -Destination $mwCDCopy;if((Get-MWCDHash $mwCDCopy) -ne $mwCDSources[$mwCDPath]){throw 'Exact literal original control source preservation'};$mwCDCopies.Add([ordered]@{original_path=$mwCDPath;preserved_path=$mwCDCopy;sha256=$mwCDSources[$mwCDPath]})}
$mwCDCommands=[Collections.Generic.List[object]]::new()
function Invoke-MWCD([string]$Program,[string[]]$Arguments,[string]$Log){$mwCDSaved=$ErrorActionPreference;$ErrorActionPreference='Continue';try{& $Program @Arguments 2>&1|Tee-Object -FilePath $Log;$mwCDExit=$LASTEXITCODE}finally{$ErrorActionPreference=$mwCDSaved};$mwCDCommands.Add([ordered]@{program=$Program;arguments=$Arguments;exit_code=$mwCDExit;log_path=$Log;log_sha256=(Get-MWCDHash $Log)});if($mwCDExit -ne 0){throw "Original control tool failed $Program exit=$mwCDExit"}}
$mwCDVS='C:/Program Files/Microsoft Visual Studio/18/Community';$mwCDPassed=$false;$mwCDFailure=$null
try{
 Import-Module (Join-Path $mwCDVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll');Enter-VsDevShell -VsInstallPath $mwCDVS -SkipAutomaticLocation -DevCmdArguments '-arch=x86 -host_arch=x64'|Out-Null
 $mwCDCMake=Join-Path $mwCDVS 'Common7/IDE/CommonExtensions/Microsoft/CMake/CMake/bin/cmake.exe'
 Invoke-MWCD $mwCDCMake @('-S',(Join-Path $PSScriptRoot 'original'),'-B',$mwCDBuild,'-G','Visual Studio 18 2026','-A','Win32',"-DMW34_DERIVED=$mwCDResearch") (Join-Path $mwCDOut 'configure.log')
 Invoke-MWCD $mwCDCMake @('--build',$mwCDBuild,'--config','Release','--verbose') (Join-Path $mwCDOut 'build.log')
 $mwCDWorker=Join-Path $mwCDBuild 'Release/mw34_control_carry_original.exe';Invoke-MWCD $mwCDWorker @('--check-protocol') (Join-Path $mwCDOut 'hash.log');foreach($mwCDPath in $mwCDSources.Keys){if((Get-MWCDHash $mwCDPath) -ne $mwCDSources[$mwCDPath]){throw 'Original control source changed during build'}};$mwCDPassed=$true
}catch{$mwCDFailure=$_.Exception.Message;$_|Out-String|Set-Content -LiteralPath (Join-Path $mwCDOut 'failure.txt');throw}finally{
 $mwCDArtifacts=[ordered]@{};foreach($mwCDFile in @(Get-ChildItem -LiteralPath $mwCDOut -File -Recurse;Get-ChildItem -LiteralPath $mwCDResearch -File -Recurse;if(Test-Path -LiteralPath $mwCDBuild){Get-ChildItem -LiteralPath $mwCDBuild -File -Recurse|Where-Object {$_.Extension -in @('.exe','.obj','.lib','.txt','.cmake','.vcxproj','.props','.json','.tlog')}})|Sort-Object FullName){$mwCDArtifacts[$mwCDFile.FullName]=Get-MWCDHash $mwCDFile.FullName}
 $mwCDTools=[ordered]@{};foreach($mwCDTool in @($mwCDCMake,(Get-Process -Id $PID).Path,(Join-Path $mwCDVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll'),(Join-Path $mwCDVS 'MSBuild/Current/Bin/amd64/MSBuild.exe'))+@('cl.exe','link.exe','rc.exe','ml.exe'|ForEach-Object {(Get-Command $_ -ErrorAction SilentlyContinue).Source})){if($mwCDTool -and (Test-Path -LiteralPath $mwCDTool)){$mwCDTools[$mwCDTool]=Get-MWCDHash $mwCDTool}}
 [ordered]@{passed=$mwCDPassed;failure=$mwCDFailure;scope='Original actual control wrapper then26selected table roots; persistent carry comparison pending';source_files=$mwCDSources;literal_source_copies=@($mwCDCopies);tool_files=$mwCDTools;artifacts=$mwCDArtifacts;commands=@($mwCDCommands);worker=$mwCDWorker;provider_path=$mwCDProvider;provider_sha256=(Get-MWCDHash $mwCDProvider);pack_path=(Join-Path $mwCDResearch 'pack.bin');pack_sha256=(Get-MWCDHash (Join-Path $mwCDResearch 'pack.bin'));whole_M4_complete=$false}|ConvertTo-Json -Depth 16|Set-Content -Encoding utf8 -LiteralPath (Join-Path $mwCDOut 'build.json')
}
